import React, { useState } from 'react';
import mqtt from 'mqtt';

export default function SendView() {
  const [message, setMessage] = useState('');
  const [status, setStatus] = useState('');

  const sendMessage = () => {

    const mqthost = localStorage.getItem('mqthost') ;
    const mqtusername = localStorage.getItem('mqtusername') ;
    const mqtpassword = localStorage.getItem('mqtpassword') ;

    const client = mqtt.connect(mqthost, {
      username: mqtusername,
      password: mqtpassword,
      protocol: 'wss'
    });
    client.on('connect', () => {
      setStatus('Connected to MQTT broker');
      client.publish('esp/test/receive', message, {}, (err) => {
        if (err) {
          setStatus('Failed to send message');
        } else {
          setStatus('Message sent successfully');
        }
        client.end();
      });
    });

    client.on('error', (err) => {
      console.error('Connection error:', err);
      setStatus('MQTT connection error');
      client.end();
    });
  };

  return (
    <div className="p-4">
      <h1 className="text-xl font-bold mb-2">Send MQTT Message</h1>
      <textarea
        className="border w-full h-40 p-2 mb-2"
        value={message}
        onChange={(e) => setMessage(e.target.value)}
        placeholder="Enter your message here..."
      ></textarea>
      <button onClick={sendMessage} className="bg-blue-600 text-white px-4 py-2">Send</button>
      <p className="mt-2 text-sm">{status}</p>
    </div>
  );
}
